function accSnapshot(array $c): array { return ['legal_form'=>$c['legal_form']??'', 'tax_system'=>$c['tax_system']??'', 'has_vat'=>(bool)$c['has_vat'], 'has_excise'=>(bool)$c['has_excise'], 'has_employees'=>(bool)$c['has_employees'], 'employee_count'=>$c['employee_count']??null, 'special_taxes'=>$c['special_taxes']??[], 'tax_income_over_40m'=>(bool)($c['module_data']['tax_income_over_40m']??false), 'tax_group'=>$c['module_data']['tax_group']??null, 'tax_profile_extra'=>$c['module_data']['tax_profile_extra']??[]]; }
function accDefaultAssignees(PDO $pdo, string $ownerId, string $obligationId, array $client, string $userId, array $members): void {
